import unittest
from candidate import flip_case

class TestFlipCase(unittest.TestCase):
    def test_flip_case_normalcase_expectedbehavior(self):
        self.assertEqual(flip_case('Hello'), 'hELLO')

    def test_flip_case_uppercase_expectedbehavior(self):
        self.assertEqual(flip_case('hELLO'), 'hello')

    def test_flip_case_mixedcase_expectedbehavior(self):
        self.assertEqual(flip_case('HeLLoWoRlD'), 'hEllOwOrLd')

    def test_flip_case_empty_string(self):
        self.assertEqual(flip_case(''), '')

    def test_flip_case_single_char_uppercase(self):
        self.assertEqual(flip_case('A'), 'a')

    def test_flip_case_single_char_lowercase(self):
        self.assertEqual(flip_case('a'), 'A')

    def test_flip_case_none_type(self):
        with self.assertRaises(TypeError):
            flip_case(None)

    def test_flip_case_type_error(self):
        with self.assertRaises(TypeError):
            flip_case(123)
